import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

// Only fix auto-generated posts (new posts from transcripts), not old WordPress posts
const autoGeneratedSlugs = [
  'utmb-100-2023-seven-years-in-the-making',
  'autumn-100-2023-today-is-a-good-day',
  'paris-marathon-2023-breaking-three-hours',
  'berlin-marathon-2022-how-not-to-pace-a-marathon',
  'london-marathon-2022-one-race-two-medals',
  'beachy-head-marathon-2022',
  'ben-nevis-ultra-2022',
  'south-downs-way-100-2023',
  'north-downs-way-100-2023',
  'thames-path-100-2023',
  'steyning-stinger-2023',
  'beachy-head-marathon-2023',
  'brighton-marathon-2024',
  'london-marathon-2024',
  'south-downs-way-100-2024',
  'swiss-alps-100-2025',
  'trans-gran-canaria-2025',
  'montane-lakeland-100-2022',
  'in-the-footsteps-of-the-dukes-of-savoy-tds-2022',
  'uts-50k-utmb-snowdonia-2022',
  'transgrancanaria-classic-2022',
  'utmb-occ-2024',
  'race-to-the-stones-2024',
  'cape-wrath-ultra-day-4-2024',
  'winter-on-the-downs-2024-storm-darragh',
  'manchester-marathon-2023',
  'hurtwood-50k-2025',
  'race-to-the-stones-2025',
  'race-to-the-king-2025',
  'ridgeway-challenge-2025',
  'manchester-marathon-2025',
  'brighton-marathon-2025'
];

function extractImages(content) {
  const images = [];
  const figureRegex = /<figure[^>]*>[\s\S]*?<img[^>]+src="([^"]+)"[^>]*>[\s\S]*?(?:<figcaption[^>]*>([\s\S]*?)<\/figcaption>)?[\s\S]*?<\/figure>/gi;
  const imgRegex = /<img[^>]+src="([^"]+)"[^>]*(?:alt="([^"]*)")?[^>]*\/?>/gi;

  let match;
  while ((match = figureRegex.exec(content)) !== null) {
    images.push({
      src: match[1],
      caption: match[2] ? match[2].replace(/<[^>]+>/g, '').trim() : null
    });
  }

  // Reset and try standalone imgs if no figures
  if (images.length === 0) {
    while ((match = imgRegex.exec(content)) !== null) {
      images.push({
        src: match[1],
        caption: match[2] || null
      });
    }
  }

  return images;
}

function removeAllImages(content) {
  let cleaned = content.replace(/<figure[^>]*>[\s\S]*?<\/figure>/gi, '');
  cleaned = cleaned.replace(/<img[^>]+\/?>/gi, '');
  cleaned = cleaned.replace(/<div[^>]*class="[^"]*image-gallery[^"]*"[^>]*>[\s\S]*?<\/div>/gi, '');
  cleaned = cleaned.replace(/<p>\s*<\/p>/gi, '');
  cleaned = cleaned.replace(/\n{3,}/g, '\n\n');
  return cleaned;
}

function createStyledImage(image, style, postTitle) {
  const { src, caption } = image;
  const alt = caption || postTitle || 'Race photo';

  if (style === 'race-photo') {
    return `
<figure class="race-photo">
  <img src="${src}" alt="${alt}" loading="lazy" />
  ${caption ? `<figcaption>${caption}</figcaption>` : ''}
</figure>`;
  } else if (style === 'float-right') {
    return `
<figure class="photo-float-right">
  <img src="${src}" alt="${alt}" loading="lazy" />
  ${caption ? `<figcaption>${caption}</figcaption>` : ''}
</figure>`;
  } else {
    return `
<figure class="photo-float-left">
  <img src="${src}" alt="${alt}" loading="lazy" />
  ${caption ? `<figcaption>${caption}</figcaption>` : ''}
</figure>`;
  }
}

function needsStyling(content) {
  const imgCount = (content.match(/<img/gi) || []).length;
  if (imgCount === 0) return false;

  const hasProperStyling = content.includes('race-photo') &&
    ((content.match(/photo-float/g) || []).length >= Math.min(imgCount - 1, 1));

  return !hasProperStyling;
}

async function fixPost(slug) {
  const post = await prisma.posts.findFirst({
    where: { slug },
    select: { id: true, slug: true, title: true, content: true }
  });

  if (!post) {
    return { slug, status: 'not found' };
  }

  if (!needsStyling(post.content)) {
    return { slug, status: 'already styled' };
  }

  const images = extractImages(post.content);
  if (images.length === 0) {
    return { slug, status: 'no images' };
  }

  // Remove existing images
  let cleanContent = removeAllImages(post.content);

  // Split into content blocks
  const blocks = cleanContent.split(/(?=<p>|<h2|<h3|<blockquote)/i).filter(b => b.trim());

  if (blocks.length < 2) {
    // Very short content - add images at end
    let result = cleanContent;
    images.forEach((img, i) => {
      const style = i === 0 ? 'race-photo' : (i % 2 === 1 ? 'float-right' : 'float-left');
      result += createStyledImage(img, style, post.title);
    });
    result += '\n<div style="clear:both"></div>';

    await prisma.posts.update({
      where: { id: post.id },
      data: { content: result }
    });

    return { slug, status: 'fixed', images: images.length };
  }

  // Calculate insertion points - distribute evenly
  const insertPoints = [];
  const spacing = Math.floor(blocks.length / (images.length + 1));
  for (let i = 0; i < images.length; i++) {
    insertPoints.push(Math.min(spacing * (i + 1), blocks.length - 1));
  }

  // Build new content
  let result = '';
  let imgIndex = 0;

  blocks.forEach((block, i) => {
    result += block;

    if (insertPoints.includes(i) && imgIndex < images.length) {
      const style = imgIndex === 0 ? 'race-photo' : (imgIndex % 2 === 1 ? 'float-right' : 'float-left');
      result += createStyledImage(images[imgIndex], style, post.title);
      imgIndex++;
    }
  });

  // Add any remaining images
  while (imgIndex < images.length) {
    const style = imgIndex === 0 ? 'race-photo' : (imgIndex % 2 === 1 ? 'float-right' : 'float-left');
    result += createStyledImage(images[imgIndex], style, post.title);
    imgIndex++;
  }

  result += '\n<div style="clear:both"></div>';

  await prisma.posts.update({
    where: { id: post.id },
    data: { content: result }
  });

  return { slug, status: 'fixed', images: images.length };
}

async function main() {
  console.log('Fixing formatting for auto-generated posts...');
  console.log('='.repeat(60));

  const results = { fixed: 0, alreadyStyled: 0, noImages: 0, notFound: 0 };

  for (const slug of autoGeneratedSlugs) {
    const result = await fixPost(slug);

    if (result.status === 'fixed') {
      console.log(`✅ ${slug} - ${result.images} images styled`);
      results.fixed++;
    } else if (result.status === 'already styled') {
      console.log(`⏭️  ${slug} - already styled`);
      results.alreadyStyled++;
    } else if (result.status === 'no images') {
      console.log(`📝 ${slug} - no images`);
      results.noImages++;
    } else {
      console.log(`❌ ${slug} - not found`);
      results.notFound++;
    }
  }

  console.log('='.repeat(60));
  console.log(`Done! Fixed: ${results.fixed}, Already OK: ${results.alreadyStyled}, No images: ${results.noImages}`);

  await prisma.$disconnect();
}

main();
